from __future__ import annotations

"""Resolving the target market for a recommendations request.

Every recommendations call should carry a market so the catalog only returns
tracks playable for the listener. A caller may pass an explicit market; if they
don't, we fall back to the listener's home market, and finally to a service
default. Markets are ISO country codes, compared case-insensitively and stored
upper-cased.
"""

from seed_catalog import SeedCatalog

FALLBACK_MARKET = "US"


def canonical_market(market: str | None) -> str | None:
    if market is None:
        return None
    token = market.strip().upper()
    return token or None


def resolve_market(
    requested: str | None,
    home_market: str | None,
    catalog: SeedCatalog,
    fallback: str = FALLBACK_MARKET,
) -> str:
    """Pick the market to send, in priority order.

    Explicit request beats the listener's home market, which beats the service
    fallback. Unsupported markets are skipped in favor of the next option.
    """

    for candidate in (requested, home_market):
        canon = canonical_market(candidate)
        if canon and catalog.is_supported_market(canon):
            return canon

    fallback_canon = canonical_market(fallback) or FALLBACK_MARKET
    if catalog.is_supported_market(fallback_canon):
        return fallback_canon
    return fallback_canon


def is_market_required(limit: int) -> bool:
    """Whether a market must accompany a request of this size.

    For any real recommendation request (a non-empty result set) the market is
    required so unplayable tracks are filtered out before they reach the player.
    """

    return limit > 0


def describe_market(market: str | None) -> str:
    if not market:
        return "market: <none>"
    return f"market: {market}"


def market_or_default(market: str | None, fallback: str = FALLBACK_MARKET) -> str:
    canon = canonical_market(market)
    return canon if canon else fallback


def same_market(left: str | None, right: str | None) -> bool:
    return canonical_market(left) == canonical_market(right)


def filter_supported(markets: list[str], catalog: SeedCatalog) -> list[str]:
    result: list[str] = []
    for market in markets:
        canon = canonical_market(market)
        if canon and catalog.is_supported_market(canon):
            result.append(canon)
    return result


def first_supported(
    candidates: list[str | None], catalog: SeedCatalog
) -> str | None:
    """Return the first candidate that is a supported market, if any."""

    for candidate in candidates:
        canon = canonical_market(candidate)
        if canon and catalog.is_supported_market(canon):
            return canon
    return None


def market_label_pair(market: str | None) -> tuple[str, str]:
    """A (key, value) pair for logging a resolved market."""

    canon = canonical_market(market)
    return ("market", canon or "<none>")

