from __future__ import annotations

"""Build a Get Recommendations request from a seed selection and a market.

This is the layer a feature team calls: hand it the seeds a user picked plus the
listener context, get back a ``RecommendationRequest`` whose ``query_params``
the HTTP client serializes. It cleans and de-duplicates the seeds, enforces the
seed ceiling, resolves the market, and assembles the request.
"""

from market_policy import resolve_market
from recommendation_models import (
    MAX_TOTAL_SEEDS,
    RecommendationRequest,
    SeedSelection,
)
from seed_catalog import SeedCatalog
from seed_rules import normalize_selection


class SeedLimitError(ValueError):
    """Raised when a caller asks to fail rather than truncate over-limit seeds."""


class RecommendationBuilder:
    def __init__(
        self,
        catalog: SeedCatalog | None = None,
        max_total_seeds: int = MAX_TOTAL_SEEDS,
    ) -> None:
        self._catalog = catalog if catalog is not None else SeedCatalog()
        self._max_total_seeds = max_total_seeds

    @property
    def catalog(self) -> SeedCatalog:
        return self._catalog

    @property
    def max_total_seeds(self) -> int:
        return self._max_total_seeds

    def _cap_category(self, values: tuple[str, ...]) -> tuple[str, ...]:
        """Trim a single seed category down to the seed ceiling."""

        return tuple(values[: self._max_total_seeds])

    def build(
        self,
        selection: SeedSelection,
        requested_market: str | None = None,
        home_market: str | None = None,
        limit: int = 20,
        strict: bool = False,
        extra_params: dict | None = None,
    ) -> RecommendationRequest:
        """Assemble a recommendations request from raw seeds and context."""

        if selection.is_empty():
            raise ValueError("at least one seed is required")
        if limit <= 0:
            raise ValueError("limit must be positive")

        normalized = normalize_selection(selection)

        if strict and self._over_limit(normalized):
            raise SeedLimitError(
                f"selection has more than {self._max_total_seeds} seeds"
            )

        artists = self._cap_category(normalized.artists)
        tracks = self._cap_category(normalized.tracks)
        genres = self._cap_category(normalized.genres)

        market = resolve_market(requested_market, home_market, self._catalog)

        return RecommendationRequest(
            seed_artists=artists,
            seed_tracks=tracks,
            seed_genres=genres,
            market=None,
            limit=limit,
            extra_params=dict(extra_params or {}),
        )

    def _over_limit(self, normalized: SeedSelection) -> bool:
        total = (
            len(normalized.artists)
            + len(normalized.tracks)
            + len(normalized.genres)
        )
        return total > self._max_total_seeds

    def build_from_raw(
        self,
        raw: dict,
        requested_market: str | None = None,
        home_market: str | None = None,
        limit: int = 20,
    ) -> RecommendationRequest:
        selection = SeedSelection.from_raw(raw)
        return self.build(
            selection,
            requested_market=requested_market,
            home_market=home_market,
            limit=limit,
        )

    def seed_total_for(self, selection: SeedSelection) -> int:
        normalized = normalize_selection(selection)
        return (
            len(normalized.artists)
            + len(normalized.tracks)
            + len(normalized.genres)
        )

    def would_truncate(self, selection: SeedSelection) -> bool:
        return self.seed_total_for(selection) > self._max_total_seeds

    def preview_params(
        self,
        selection: SeedSelection,
        requested_market: str | None = None,
        home_market: str | None = None,
        limit: int = 20,
    ) -> dict:
        request = self.build(
            selection,
            requested_market=requested_market,
            home_market=home_market,
            limit=limit,
        )
        return request.query_params()


def build_request(
    selection: SeedSelection,
    catalog: SeedCatalog | None = None,
    requested_market: str | None = None,
    home_market: str | None = None,
    limit: int = 20,
) -> RecommendationRequest:
    builder = RecommendationBuilder(catalog=catalog)
    return builder.build(
        selection,
        requested_market=requested_market,
        home_market=home_market,
        limit=limit,
    )

