from __future__ import annotations

"""Models for a Get Recommendations request.

A recommendation call is seeded by some mix of artists, tracks, and genres. The
public API treats those three lists as one pool: the *combined* number of seeds
across all three categories has a hard ceiling. A request also carries a target
``market`` so the catalog only returns tracks that are actually playable for the
listener; without it the player ends up skipping tracks it can't start.

These dataclasses are the plain data the rest of the flow folds together. The
builder turns a ``SeedSelection`` plus a market into a ``RecommendationRequest``
whose ``query_params`` are what the HTTP layer would serialize.
"""

from dataclasses import dataclass, field

# Spotify caps the *combined* seed count across artists + tracks + genres.
MAX_TOTAL_SEEDS = 5


@dataclass(frozen=True)
class SeedSelection:
    """Raw seed input as it arrives from a client, before normalization."""

    artists: tuple[str, ...] = ()
    tracks: tuple[str, ...] = ()
    genres: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        for label, values in (
            ("artists", self.artists),
            ("tracks", self.tracks),
            ("genres", self.genres),
        ):
            if not isinstance(values, tuple):
                raise TypeError(f"{label} must be a tuple of strings")

    @classmethod
    def from_raw(cls, raw: dict) -> "SeedSelection":
        return cls(
            artists=tuple(str(a) for a in raw.get("seed_artists", []) or []),
            tracks=tuple(str(t) for t in raw.get("seed_tracks", []) or []),
            genres=tuple(str(g) for g in raw.get("seed_genres", []) or []),
        )

    def raw_total(self) -> int:
        return len(self.artists) + len(self.tracks) + len(self.genres)

    def is_empty(self) -> bool:
        return self.raw_total() == 0


@dataclass(frozen=True)
class RecommendationRequest:
    """A built, ready-to-serialize recommendations request."""

    seed_artists: tuple[str, ...]
    seed_tracks: tuple[str, ...]
    seed_genres: tuple[str, ...]
    market: str | None = None
    limit: int = 20
    extra_params: dict = field(default_factory=dict)

    def seed_total(self) -> int:
        return len(self.seed_artists) + len(self.seed_tracks) + len(self.seed_genres)

    def query_params(self) -> dict:
        params: dict[str, object] = {}
        if self.seed_artists:
            params["seed_artists"] = ",".join(self.seed_artists)
        if self.seed_tracks:
            params["seed_tracks"] = ",".join(self.seed_tracks)
        if self.seed_genres:
            params["seed_genres"] = ",".join(self.seed_genres)
        params["limit"] = self.limit
        if self.market:
            params["market"] = self.market
        for key, value in self.extra_params.items():
            params[key] = value
        return params

    def has_market(self) -> bool:
        return bool(self.market)


def normalize_token(value: str) -> str:
    """Trim surrounding whitespace from a seed token."""

    return value.strip()


def fold_key(value: str) -> str:
    """Canonical comparison key for a seed: trimmed and lowercased."""

    return value.strip().lower()


def build_selection(
    artists: list[str] | None = None,
    tracks: list[str] | None = None,
    genres: list[str] | None = None,
) -> SeedSelection:
    return SeedSelection(
        artists=tuple(artists or []),
        tracks=tuple(tracks or []),
        genres=tuple(genres or []),
    )

