from __future__ import annotations

"""Reference data for valid recommendation seeds.

Genres are drawn from a fixed list the catalog publishes. Artist and track seeds
are opaque IDs the client supplies; we only check they look like IDs and aren't
blank. The catalog also knows which markets the service is enabled in, so the
builder can resolve a default market when a caller doesn't pass one.
"""

from recommendation_models import fold_key

# A small slice of the published genre seeds.
DEFAULT_GENRES = (
    "acoustic",
    "afrobeat",
    "alt-rock",
    "ambient",
    "blues",
    "chill",
    "classical",
    "dance",
    "electronic",
    "folk",
    "hip-hop",
    "house",
    "indie",
    "jazz",
    "metal",
    "pop",
    "punk",
    "r-n-b",
    "reggae",
    "rock",
    "soul",
    "techno",
)

DEFAULT_MARKETS = ("US", "GB", "DE", "AU", "JP", "BR", "CA", "FR")


class SeedCatalog:
    def __init__(
        self,
        genres: list[str] | None = None,
        markets: list[str] | None = None,
    ) -> None:
        source_genres = genres if genres is not None else list(DEFAULT_GENRES)
        self._genres: set[str] = {fold_key(g) for g in source_genres}
        source_markets = markets if markets is not None else list(DEFAULT_MARKETS)
        self._markets: set[str] = {m.strip().upper() for m in source_markets}

    def is_known_genre(self, genre: str) -> bool:
        return fold_key(genre) in self._genres

    def known_genres(self) -> list[str]:
        return sorted(self._genres)

    def genre_count(self) -> int:
        return len(self._genres)

    def add_genre(self, genre: str) -> None:
        self._genres.add(fold_key(genre))

    def is_supported_market(self, market: str) -> bool:
        return market.strip().upper() in self._markets

    def supported_markets(self) -> list[str]:
        return sorted(self._markets)

    def market_count(self) -> int:
        return len(self._markets)


def looks_like_id(value: str) -> bool:
    """Whether a token is a plausible artist/track seed ID.

    Spotify IDs are non-empty alphanumeric strings (base62). We accept anything
    non-blank that is alphanumeric after trimming; this is intentionally loose.
    """

    token = value.strip()
    if not token:
        return False
    return token.isalnum()


def is_valid_seed_value(value: str) -> bool:
    return bool(value) and bool(value.strip())


def partition_known_genres(
    genres: list[str], catalog: SeedCatalog
) -> tuple[list[str], list[str]]:
    """Split genres into (known, unknown) preserving order."""

    known: list[str] = []
    unknown: list[str] = []
    for genre in genres:
        if catalog.is_known_genre(genre):
            known.append(genre)
        else:
            unknown.append(genre)
    return known, unknown


def build_catalog(
    genres: list[str] | None = None, markets: list[str] | None = None
) -> SeedCatalog:
    return SeedCatalog(genres=genres, markets=markets)

