from __future__ import annotations

"""Normalization and de-duplication rules for recommendation seeds.

Before any seed limit is applied, the seed pool has to be reduced to its real
distinct members. Clients send messy input: the same artist twice, a genre with
trailing spaces, a track that also appears under a different casing, or the same
ID present in two categories. The count that matters for the seed ceiling is the
count *after* this collapsing happens.
"""

from recommendation_models import SeedSelection, fold_key, normalize_token


def _clean(values: tuple[str, ...]) -> list[str]:
    """Drop blanks and trim each token, keeping order."""

    cleaned: list[str] = []
    for value in values:
        token = normalize_token(value)
        if token:
            cleaned.append(token)
    return cleaned


def dedupe_category(values: tuple[str, ...]) -> list[str]:
    """Collapse repeats inside a single seed category, first occurrence wins."""

    seen: set[str] = set()
    result: list[str] = []
    for token in _clean(values):
        if token not in seen:
            seen.add(token)
            result.append(token)
    return result


def normalize_selection(selection: SeedSelection) -> SeedSelection:
    """Clean and de-duplicate a selection's three categories."""

    return SeedSelection(
        artists=tuple(dedupe_category(selection.artists)),
        tracks=tuple(dedupe_category(selection.tracks)),
        genres=tuple(dedupe_category(selection.genres)),
    )


def distinct_seed_count(selection: SeedSelection) -> int:
    """How many distinct seeds the selection really contains."""

    normalized = normalize_selection(selection)
    return (
        len(normalized.artists)
        + len(normalized.tracks)
        + len(normalized.genres)
    )


def exceeds_limit(selection: SeedSelection, max_total: int) -> bool:
    return distinct_seed_count(selection) > max_total


def fold_keys(values: tuple[str, ...]) -> list[str]:
    """Comparison keys for a category's tokens."""

    return [fold_key(v) for v in _clean(values)]


def has_internal_duplicates(values: tuple[str, ...]) -> bool:
    keys = fold_keys(values)
    return len(keys) != len(set(keys))


def overlap_keys(left: tuple[str, ...], right: tuple[str, ...]) -> set[str]:
    """Comparison keys present in both categories."""

    return set(fold_keys(left)) & set(fold_keys(right))


def merge_preserving_order(*groups: list[str]) -> list[str]:
    """Concatenate already-cleaned groups, dropping later exact repeats."""

    seen: set[str] = set()
    merged: list[str] = []
    for group in groups:
        for token in group:
            if token not in seen:
                seen.add(token)
                merged.append(token)
    return merged


def summarize_selection(selection: SeedSelection) -> dict[str, int]:
    normalized = normalize_selection(selection)
    return {
        "artists": len(normalized.artists),
        "tracks": len(normalized.tracks),
        "genres": len(normalized.genres),
        "total": distinct_seed_count(selection),
    }

